/**
 * MT5 ".set" preset for the TradeDeskSync EA, so the user loads the key with
 * Inputs → Load instead of copying it. MetaTrader writes these files as
 * UTF-16LE with a byte-order mark and one `Name=value` per line.
 */
export function eaSetFileText(apiUrl: string, syncKey: string): string {
  return [
    '; TradeDeskSync settings, generated by TradeDesk. Keep this file private: it contains your sync key.',
    `ApiUrl=${apiUrl}`,
    `SyncKey=${syncKey}`,
    'HistoryDaysOnStart=90',
    'BatchSize=200',
    'HeartbeatSeconds=30',
    'EnableLog=true',
    'ServerTimeZone=0',
    'FixedOffsetHours=2',
    '',
  ].join('\r\n')
}

/** UTF-16LE bytes with BOM, the encoding MetaTrader uses for .set files. */
export function utf16leWithBom(text: string): Uint8Array {
  const out = new Uint8Array(2 + text.length * 2)
  out[0] = 0xff
  out[1] = 0xfe
  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i)
    out[2 + i * 2] = c & 0xff
    out[3 + i * 2] = c >> 8
  }
  return out
}
